def r13_where(person):
    if person == "guard":
        # All playable time periods show the same staffed checkpoint.
        # Neither entry_corrected nor the family's case state ends duty.
        return "gate"
    return _r13_before_gate_where(person)

def r13_where(person):
    if person=="daram":return store.room13["location"] if r13_home_with_daram() else None
    return _r13_home_where(person)

def r13_resident_where(person):
    if person not in R13_RESIDENTS:return None
    s=store.room13
    if person=="resident_piko" and s["day"]>=R13_WEEK2_DAY:return "clinic"
    if person=="resident_badook" and s["day"]>=R13_WEEK2_DAY and r13_has("patient_transport"):return "school"
    if s["day"]>=r13_tl(11) and r13_has("shelter_ready") and person in ("resident_tori","resident_yeoni","resident_kongi","resident_somi","resident_musoe"):
        return "school"
    where=R13_WEEKLY_ROUTINES.get(person,R13_RESIDENTS[person]["weekly_locations"])[(s["day"]-1)%7][min(s["period"],2)]
    return {"home":None,"library":"post","lowroad":"gate","tower":"square"}.get(where,where)

def r13_where(person):
    s=store.room13; p=min(s["period"],2)
    if s["day"]>=R13_WEEK2_DAY:return r13_w2_where(person)
    if person=="resident_owlgp":
        if s["victim_state"]=="dead":return None
        return ("square","inn","dining")[p]
    if person=="granny":return None if s["granny_state"]=="detained" else "inn"
    if person=="nabi":return r13_nabi_daily_where(s)
    if person=="buri":return "workshop"
    if person=="karo":return "gate"
    if person=="seryeon":return "post" if s["day"]>=2 and p<2 else None
    if person=="resident_tok":return "workshop" if p<2 else "dining"
    if person=="resident_lamplighter":return ("workshop","square","gate")[p]
    if person=="doto":return "hall" if s["day"]>=R13_CASE_DAY+1 else "square"
    if person=="bami":
        if s["case_state"]!="occurred":return None
        return "inn" if r13_has("bami_protected") else "hall" if p>0 else None
    if person=="neoul":return "gate" if s["case_state"]=="occurred" else None
    if person=="resident_seori":return "clinic"
    return r13_resident_where(person)

def r13_where(person):
    s=store.room13 or {}
    pins=R13_STORY_PINS.get((s.get("day"),min(s.get("period",0),2)))
    if pins and person in pins:return pins[person]
    return _r13_alibi_where(person)

def r13_where(person):
    if person=="resident_musoe":
        if r13_has("musoe_gone"):return None
        if r13_has("kd_seori"):return "clinic"
    return _r13_kd_where(person)

def r13_where(person):
    if person=="resident_lamplighter":
        if r13_has("chorong_dead"):return None
        if r13_has("nt_chorong_half") and r13_has("nt_night8"):return "clinic"
    if person=="resident_ttadak":
        if r13_has("ttadak_dead"):return None
        if r13_has("nt_ttadak_half") and r13_has("nt_dawn9"):return "clinic"
    return _r13_nt_where(person)

def r13_where(person):
    if person=="bami" and r13_has("bami_taken"):return None
    if person=="resident_tok" and r13_has("tok_detained") and not r13_has("tok_cleared"):return None
    return _r13_episode_where(person)

def r13_where(person):
    if person=="karo" and store.room13.get("day")==2 and not r13_has("livelihood_open"):
        return "gate"
    return _r13_life_where(person)

def r13_where(person):
    flag=R13_DEATH_FLAGS.get(person)
    if flag and store.room13 and r13_has(flag):return None
    return _r13_continuity_where(person)
